#!/usr/bin/env bash
# Refuses a formula that differs from the tap's current one in more than the lines a release may
# change. Usage: check-diff.sh CURRENT FORMULA. Prints the differing lines and one
# `release: ...` line to stderr and exits 1 on a refusal; prints nothing and exits 0 otherwise
# (the caller has already found the files to differ).
set -euo pipefail
current=${1:?usage: check-diff.sh CURRENT FORMULA}
formula=${2:?formula}
# diff exits 1 when the files differ; under pipefail that would end the script silently, so its
# status is dropped (2, trouble, cannot happen: the caller fetched and wrote both files).
changed=$({ diff -U0 "$current" "$formula" || true; } | { grep -E '^[+-]' || true; } |
  { grep -Ev '^(\+\+\+|---)' || true; })
# url, version and sha256 change every release. The other lines are what the move to one
# universal binary changes, once: the header comment and the two comment lines that say why the
# arm64-only dependency stays.
allowed='^[+-] *(url|version|sha256) "|^[+-]# zbx for macOS|^-  depends_on arch: :arm64$'
allowed+='|^\+  # The universal zip carries an x86_64 slice|^\+  # silicon: an Intel Mac is refused'
# The move from Zigbox/zigbox to ZigboxOrg/zigbox and from MIT to Apache-2.0 (0.6.0) changes these
# lines once, each from exactly the old text to exactly the new: whole lines, compared as fixed
# strings, so no other homepage, licence or comment passes, and the change cannot be undone.
# shellcheck disable=SC2016 # the backquotes are the formula's own text, not a command
moved=(
  '-# Generated by `zig build mac-release` in Zigbox/zigbox from packaging/homebrew/zigbox.rb, which'
  '+# Generated by `zig build mac-release` in ZigboxOrg/zigbox from packaging/homebrew/zigbox.rb, which'
  '-  homepage "https://github.com/Zigbox/zigbox"'
  '+  homepage "https://github.com/ZigboxOrg/zigbox"'
  '-  # zbx is MIT; the binary carries a Linux kernel and VM tools under the GPL (sources on the'
  '+  # zbx is Apache-2.0; the binary carries a Linux kernel and VM tools under the GPL (sources on the'
  '-  # vm-kernel-6.18.59 and vm-deps-alpine-3.20 releases of Zigbox/zigbox).'
  '+  # vm-kernel-6.18.59 and vm-deps-alpine-3.20 releases of ZigboxOrg/zigbox).'
  '-  license all_of: ["MIT", "GPL-2.0-only"]'
  '+  license all_of: ["Apache-2.0", "GPL-2.0-only"]'
)
rest=$({ grep -Ev "$allowed" <<<"$changed" || true; } |
  { grep -Fxv -f <(printf '%s\n' "${moved[@]}") || true; })
if [ -n "$rest" ]; then
  printf '%s\n' "$rest" >&2
  echo "release: the formula differs from the tap's in more than url, version and sha256" >&2
  exit 1
fi
